import json


def diff(a, b):
    ops = []
    _walk(a, b, "$", ops)
    return sorted(ops)


def _walk(a, b, path, ops):
    if isinstance(a, dict) and isinstance(b, dict):
        for key in sorted(set(a) | set(b), key=str):
            child = f"{path}.{key}"
            if key not in b:
                _emit(ops, "-", child, a[key])
            elif key not in a:
                _emit(ops, "+", child, b[key])
            else:
                _walk(a[key], b[key], child, ops)
    elif isinstance(a, list) and isinstance(b, list):
        for i in range(max(len(a), len(b))):
            child = f"{path}[{i}]"
            if i >= len(b):
                _emit(ops, "-", child, a[i])
            elif i >= len(a):
                _emit(ops, "+", child, b[i])
            else:
                _walk(a[i], b[i], child, ops)
    elif type(a) is type(b) and a == b:
        return
    else:
        ops.append(f"~ {path}: {_fmt(a)} -> {_fmt(b)}")


def _emit(ops, sign, path, value):
    ops.append(f"{sign} {path}: {_fmt(value)}")


def _fmt(value):
    return json.dumps(value, sort_keys=True)
```

